def esc(v):
    v = v.replace('&', '&amp;').replace('<', '&lt;').replace("'", "\\'").replace('"', '\\"')
    return v.replace('\n', '\\n')


for d, i in {'values': 0, 'values-ru': 1, 'values-uk': 2}.items():
    os.makedirs(os.path.join(RES, d), exist_ok=True)
    lines = ['<?xml version="1.0" encoding="utf-8"?>', '<resources>']
    if i == 0:
        lines.append('    <string name="app_name">ADB-phon</string>')
    for k, v in S.items():
        lines.append(f'    <string name="{k}">{esc(v[i])}</string>')
    lines.append('</resources>')
    open(os.path.join(RES, d, 'strings.xml'), 'w', encoding='utf-8').write('\n'.join(lines) + '\n')
print(len(S), 'строк')
